--
-- Table structure for table `inventory_check_details`
--

DROP TABLE IF EXISTS `inventory_check_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inventory_check_details` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '盘点明细ID',
  `task_id` bigint(20) NOT NULL COMMENT '任务ID',
  `drug_id` bigint(20) NOT NULL COMMENT '药品ID',
  `system_stock` int(11) NOT NULL COMMENT '系统理论库存',
  `actual_stock` int(11) DEFAULT NULL COMMENT '实际盘点库存',
  `discrepancy` int(11) DEFAULT NULL COMMENT '差异数量 (实际 - 理论)',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `actual_amount` decimal(10,2) DEFAULT NULL COMMENT '期末实盘金额',
  `log_content` varchar(255) DEFAULT NULL COMMENT '盘点日志内容',
  PRIMARY KEY (`id`),
  KEY `drug_id` (`drug_id`),
  KEY `task_id` (`task_id`),
  CONSTRAINT `inventory_check_details_ibfk_1` FOREIGN KEY (`task_id`) REFERENCES `inventory_check_tasks` (`id`),
  CONSTRAINT `inventory_check_details_ibfk_2` FOREIGN KEY (`drug_id`) REFERENCES `drugs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1766 DEFAULT CHARSET=utf8mb4 COMMENT='库存盘点明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

