--
-- Table structure for table `patient_visits`
--

DROP TABLE IF EXISTS `patient_visits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `patient_visits` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '就诊ID',
  `doctor_id` bigint(20) NOT NULL COMMENT '医师ID',
  `patient_name` varchar(50) NOT NULL COMMENT '患者姓名',
  `gender` varchar(10) DEFAULT NULL COMMENT '性别',
  `age` int(11) DEFAULT NULL COMMENT '年龄',
  `diagnosis_id` bigint(20) DEFAULT NULL COMMENT '诊断类型ID',
  `visit_date` date NOT NULL COMMENT '就诊日期',
  `status` enum('DRAFT','SUBMITTED','RETURNED','COMPLETED','CANCELED') DEFAULT 'DRAFT' COMMENT '状态: 草稿/待发药/已退回/已完成',
  `return_reason` varchar(255) DEFAULT NULL COMMENT '退回原因',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `custom_diagnosis` varchar(255) DEFAULT NULL COMMENT '自定义诊断内容',
  `department` varchar(6) DEFAULT NULL COMMENT '部门',
  PRIMARY KEY (`id`),
  KEY `diagnosis_id` (`diagnosis_id`),
  KEY `doctor_id` (`doctor_id`),
  KEY `idx_visit_date` (`visit_date`),
  KEY `idx_status` (`status`),
  CONSTRAINT `patient_visits_ibfk_1` FOREIGN KEY (`doctor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `patient_visits_ibfk_2` FOREIGN KEY (`diagnosis_id`) REFERENCES `diagnosis_types` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=584 DEFAULT CHARSET=utf8mb4 COMMENT='患者就诊记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `patient_visits`
--

LOCK TABLES `patient_visits` WRITE;
/*!40000 ALTER TABLE `patient_visits` DISABLE KEYS */;
