--
-- Table structure for table `purchase_details`
--

DROP TABLE IF EXISTS `purchase_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `purchase_details` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '购进记录ID',
  `drug_id` bigint(20) NOT NULL COMMENT '药品ID',
  `quantity` int(11) NOT NULL COMMENT '购进数量',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位',
  `price` decimal(10,2) NOT NULL COMMENT '购进单价',
  `total_amount` decimal(10,2) NOT NULL COMMENT '购进总金额',
  `purchase_date` date NOT NULL COMMENT '购进日期',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `batch_id` bigint(20) DEFAULT NULL COMMENT '关联批次ID',
  PRIMARY KEY (`id`),
  KEY `drug_id` (`drug_id`),
  KEY `idx_batch_id` (`batch_id`),
  KEY `idx_purchase_date` (`purchase_date`),
  CONSTRAINT `purchase_details_ibfk_1` FOREIGN KEY (`drug_id`) REFERENCES `drugs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=91 DEFAULT CHARSET=utf8mb4 COMMENT='药品购进明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

