--
-- Table structure for table `purchase_plan_details`
--

DROP TABLE IF EXISTS `purchase_plan_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `purchase_plan_details` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `plan_id` bigint(20) NOT NULL COMMENT '计划ID',
  `drug_id` bigint(20) NOT NULL COMMENT '药品ID',
  `spec` varchar(100) DEFAULT NULL COMMENT '规格（快照）',
  `unit` varchar(50) DEFAULT NULL COMMENT '单位（快照）',
  `purchase_price` decimal(10,2) DEFAULT NULL COMMENT '进货价（取自最新批次）',
  `manufacturer` varchar(255) DEFAULT NULL COMMENT '生产厂家（可编辑）',
  `planned_quantity` int(11) DEFAULT NULL COMMENT '计划数量（药师必填）',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `plan_id` (`plan_id`),
  KEY `drug_id` (`drug_id`),
  CONSTRAINT `purchase_plan_details_ibfk_1` FOREIGN KEY (`plan_id`) REFERENCES `purchase_plans` (`id`),
  CONSTRAINT `purchase_plan_details_ibfk_2` FOREIGN KEY (`drug_id`) REFERENCES `drugs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=288 DEFAULT CHARSET=utf8mb4 COMMENT='采购计划明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

